#include <bits/stdc++.h>
using namespace std;
​
// 好友图的邻接表
unordered_map<string, unordered_set<string>> graph;
​
// 结果：极大团（朋友圈）的数量
int countAns = 0;
​
// Tomita 最优 pivot:
// 选择 P ∪ X 中 "度数最大" 的点作为 pivot
string choosePivotMaxDegree(const unordered_set<string>& P, const unordered_set<string>& X) {
    string best;
    int maxDeg = -1;
​
    // 合并 P ∪ X
    unordered_set<string> all = P;
    all.insert(X.begin(), X.end());
​
    for (const string& v : all) {
        int deg = graph[v].size();
        if (deg > maxDeg) {
            maxDeg = deg;
            best = v;
        }
    }
    return best;
}
​
/**
 * Tomita 优化 Bron–Kerbosch 搜索最大团
 * R: 当前团
 * P: 可能扩展 R 的点
 * X: 已经尝试过的点（不能再加到 R）
 */
void bronKerboschTomita(unordered_set<string> R,
                        unordered_set<string> P,
                        unordered_set<string> X) {
​
    // 终止条件：P 和 X 都为空，说明 R 是极大团 ---
    if (P.empty() && X.empty()) {
        if (R.size() >= 3) {   // 至少 3 人才算朋友圈
            countAns++;
        }
        return;
    }
​
    // 选择 pivot：P ∪ X 中度数最大的点（Tomita 优化）
    string pivot = choosePivotMaxDegree(P, X);
​
    // pivot 的邻居
    const unordered_set<string>& pivotNei = graph[pivot];
​
    // 只遍历 P - N(pivot)
    vector<string> toIterate;
    for (const string& v : P) {
        if (!pivotNei.count(v)) {
            toIterate.push_back(v);
        }
    }
​
    for (const string& v : toIterate) {
​
        // R ∪ {v}
        unordered_set<string> R2 = R;
        R2.insert(v);
​
        // P ∩ N(v)
        unordered_set<string> P2;
        for (const string& u : P) {
            if (graph[v].count(u)) P2.insert(u);
        }
​
        // X ∩ N(v)
        unordered_set<string> X2;
        for (const string& u : X) {
            if (graph[v].count(u)) X2.insert(u);
        }
​
        // 递归
        bronKerboschTomita(R2, P2, X2);
​
        // 回溯：从 P 移除 v，加入 X
        P.erase(v);
        X.insert(v);
    }
}
​
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
​
    int N;
    cin >> N;
​
    // 构建无向图
    for (int i = 0; i < N; i++) {
        string line;
        cin >> line;
        stringstream ss(line);
        string a, b;
        getline(ss, a, ',');
        getline(ss, b, ',');
​
        graph[a].insert(b);
        graph[b].insert(a);
    }
​
    // 初始化 P：所有节点
    unordered_set<string> R, P, X;
    for (auto& kv : graph) P.insert(kv.first);
​
    // 调用 Tomita BK 算法
    bronKerboschTomita(R, P, X);
​
    cout << countAns << "\n";
    return 0;
}
