package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
)
​
// 好友图的邻接表
var graph = map[string]map[string]bool{}
// 结果：极大团（朋友圈）的数量
var count int
​
// Tomita 最优 pivot:
// 选择 P ∪ X 中 "度数最大" 的点作为 pivot
func choosePivotMaxDegree(P, X map[string]bool) string {
    all := map[string]bool{}
    for k := range P { all[k] = true }
    for k := range X { all[k] = true }
​
    best := ""
    maxDeg := -1
​
    for v := range all {
        deg := len(graph[v])
        if deg > maxDeg {
            maxDeg = deg
            best = v
        }
    }
    return best
}
​
// 计算集合交集
func intersect(a, b map[string]bool) map[string]bool {
    res := map[string]bool{}
    for k := range a {
        if b[k] {
            res[k] = true
        }
    }
    return res
}
​
// Tomita 优化 Bron–Kerbosch 搜索最大团
// R: 当前团
// P: 可能扩展 R 的点
// X: 已经尝试过的点（不能再加到 R）
func bronKerboschTomita(R, P, X map[string]bool) {
    // 终止条件：P 和 X 都为空，说明 R 是极大团 ---
    if len(P) == 0 && len(X) == 0 {
        if len(R) >= 3 {   // 至少 3 人才算朋友圈
            count++
        }
        return
    }
​
    // 选择 pivot：P ∪ X 中度数最大的点（Tomita 优化）
    pivot := choosePivotMaxDegree(P, X)
    pivotNei := graph[pivot]
​
    // 只遍历 P - N(pivot)
    toIterate := []string{}
    for v := range P {
        if !pivotNei[v] {
            toIterate = append(toIterate, v)
        }
    }
​
    for _, v := range toIterate {
        // R ∪ {v}
        R2 := map[string]bool{}
        for k := range R { R2[k] = true }
        R2[v] = true
​
        // P ∩ N(v)
        P2 := intersect(P, graph[v])
        // X ∩ N(v)
        X2 := intersect(X, graph[v])
​
        // 递归
        bronKerboschTomita(R2, P2, X2)
​
        // 回溯：从 P 移除 v，加入 X
        delete(P, v)
        X[v] = true
    }
}
​
func main() {
    in := bufio.NewReader(os.Stdin)
    var N int
    fmt.Fscan(in, &N)
​
    // 构建无向图
    for i := 0; i < N; i++ {
        var line string
        fmt.Fscan(in, &line)
        parts := strings.Split(line, ",")
        a, b := parts[0], parts[1]
​
        if graph[a] == nil { graph[a] = map[string]bool{} }
        if graph[b] == nil { graph[b] = map[string]bool{} }
        graph[a][b] = true
        graph[b][a] = true
    }
​
    // 初始化 P：所有节点
    R := map[string]bool{}
    P := map[string]bool{}
    X := map[string]bool{}
​
    for k := range graph { P[k] = true }
​
    // 调用 Tomita BK 算法
    bronKerboschTomita(R, P, X)
​
    fmt.Println(count)
}
